/* home.steps — หน้าแรก · ขั้นตอนการผลิต (6 rows) */
IF NOT EXISTS (SELECT 1 FROM dbo.lyiweb_items WHERE list_key = N'home.steps')
BEGIN
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.steps', 10, N'{"title":"เส้นด้าย & วัตถุดิบคุณภาพ","short":"เส้นด้าย","desc":"คัดเลือกเส้นด้าย ทั้งโพลีเอสเตอร์ ไนลอน และสแปนเดกซ์ ให้เหมาะกับโครงสร้าง ความยืดหยุ่น และสัมผัสที่ต้องการของแต่ละชิ้นงาน"}', NULL, N'{"n":"01","tag":"OEKO-TEX® STANDARD","img":"assets/img/process/bgvideo1.jpg"}');
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.steps', 20, N'{"title":"ทอ / ถัก / ถักเชือก","short":"ทอ/ถัก/ถักเชือก","desc":"เครื่องจักรรองรับโครงสร้างงานทอ งานถัก และงานถักเชือกหลากหลายรูปแบบ ตั้งแต่งานละเอียด เนื้อนุ่ม ไปจนถึงงานที่ต้องการรับแรงสูง"}', NULL, N'{"n":"02","tag":"WEAVING · KNITTING · BRAIDING","img":"assets/img/process/nl.jpg"}');
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.steps', 30, N'{"title":"โรงย้อมและห้องแล็บภายใน","short":"ย้อมสีและแล็บ","desc":"ระบบจ่ายสีย้อมอัตโนมัติ ควบคุมสูตรด้วยคอมพิวเตอร์ เทียบสีตามผ้าตัวอย่างและรหัส Pantone พร้อมจัดทำ Lab dip เพื่ออนุมัติสี ควบคุมคุณภาพสีตามมาตรฐานที่กำหนดในทุกล็อตการสั่งซื้อ"}', NULL, N'{"n":"03","tag":"PANTONE MATCHING","img":""}');
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.steps', 40, N'{"title":"Finishing — งานตกแต่งสำเร็จ","short":"Finishing","desc":"งานสกรีน พิมพ์ Sublimation ทำปลายเชือก (Tipping) ด้วยซิลิโคน โลหะ และฟิล์ม เคลือบซิลิโคนกันลื่น ตัดตามความยาว และปั๊มนูน–จม ทั้งตัวอักษรและโลโก้ พร้อมนำไปเย็บประกอบบนชิ้นงาน"}', NULL, N'{"n":"04","tag":"VERSATILE FINISHING","img":"assets/img/process/BRAIDING.jpg"}');
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.steps', 50, N'{"title":"QC ตรวจสอบคุณภาพทุกล็อต","short":"QC ทุกล็อต","desc":"ตรวจสอบคุณภาพและทดสอบคุณสมบัติด้วยห้องแล็บภายใน ทั้งแรงดึง ความยืดหยุ่นหลังซัก และความคงทนของสี (Colorfastness) เพื่อให้ชิ้นงานผ่านเกณฑ์มาตรฐานที่กำหนดก่อนส่งมอบ"}', NULL, N'{"n":"05","tag":"IN-HOUSE LAB & QC","img":"assets/img/process/FINISHING.jpg"}');
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.steps', 60, N'{"title":"ส่งมอบตรงเวลา ซัพพลายเออร์เดียว","short":"ส่งมอบตรงเวลา","desc":"ซัพพลายเออร์รายเดียวรับผิดชอบคุณภาพตลอดสาย ลด lead time และตัดปัญหาความผิดพลาดในการประสานงานระหว่างโรงงานย่อย"}', NULL, N'{"n":"06","tag":"RELIABLE DELIVERY","img":"assets/img/process/CROCHET.jpg"}');
END

