/* home.faq — หน้าแรก · คำถามที่พบบ่อย (4 rows) */
IF NOT EXISTS (SELECT 1 FROM dbo.lyiweb_items WHERE list_key = N'home.faq')
BEGIN
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.faq', 10, N'{"q":"สั่งผลิตขั้นต่ำ (MOQ) อยู่ที่เท่าไหร่?","a":"เรารองรับการสั่งผลิตจำนวนน้อยได้ ขั้นต่ำขึ้นอยู่กับประเภทชิ้นงาน โครงสร้าง และสี — ทั้งงานทดลองตลาด คอลเลกชันขนาดเล็ก ไปจนถึงออเดอร์ปริมาณมาก ส่วนงานพัฒนาใหม่ (R&D) เราจัดทำชิ้นงานตัวอย่าง (Sample Run) เพื่อทดสอบฟังก์ชันและสีก่อนผลิตจริงได้ ส่งแบบหรือโจทย์การใช้งานมาให้ทีมฝ่ายขายประเมินได้เลย"}', NULL, NULL);
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.faq', 20, N'{"q":"เทียบสีตามรหัส Pantone หรือตัวอย่างจริงได้ไหม?","a":"ได้แน่นอนครับ โรงงานมีโรงย้อมมาตรฐานในตัวและห้องแล็บเทียบสีอัตโนมัติ รองรับทั้งระบบ Pantone Matching System (TCX), การทำ Lab-dip และการเทียบสีตามชิ้นงานจริงของลูกค้า พร้อมการันตีค่าความต่างของสี (Delta-E) ให้อยู่ในเกณฑ์มาตรฐานที่แบรนด์กีฬาระดับโลกยอมรับ"}', NULL, NULL);
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.faq', 30, N'{"q":"ระยะเวลาในการพัฒนาตัวอย่างและผลิตจริงใช้เวลากี่วัน?","a":"การทำชิ้นงานตัวอย่าง (Sample Development) ใช้เวลาประมาณ 7 – 14 วันทำการหลังยืนยันแบบและเฉดสี สำหรับการผลิตล็อตจริงใช้เวลาประมาณ 20 – 30 วันทำการ ขึ้นอยู่กับปริมาณและความซับซ้อนของเทคนิคการตกแต่ง (Finishing)"}', NULL, NULL);
    INSERT dbo.lyiweb_items (list_key, sort_order, data_th, data_en, data_common) VALUES (N'home.faq', 40, N'{"q":"รับบริการพัฒนาสินค้าตามแบบเฉพาะ (OEM / ODM) หรือไม่?","a":"รับครับ ทีมงาน R&D ของเรามีประสบการณ์กว่า 40 ปีในการร่วมงานกับดีไซเนอร์และผู้จัดการฝ่ายจัดซื้อของแบรนด์กีฬาระดับโลก ตั้งแต่การให้คำปรึกษาเรื่องโครงสร้างเส้นด้าย การเลือกใช้วัสดุรีไซเคิล (Recycled Yarn) การปรับแรงดึง ไปจนถึงการขึ้นตัวอย่างเพื่อทดสอบการเย็บจริง"}', NULL, NULL);
END

COMMIT TRANSACTION;

/* ตรวจผล */
SELECT list_key, COUNT(*) AS rows_count FROM dbo.lyiweb_items GROUP BY list_key ORDER BY list_key;
